        // 	// 使用布局求解器计算新位置
        // 	this.layoutSolver.setPageHeight(viewport.height);
        // 	const newPositions = this.layoutSolver.solve(cards);
        // 	// 应用新位置（修改 data.position.rects 而不是 style.top）
