            let cardWidth = VIBE_CARD_CONFIG.defaultWidth; // VibeCard默认宽度
            let cardHeight = 60; // VibeCard默认高度
            let newPosition = {
              pageIndex: position.pageIndex,
              fontSize: 14,
              rotation: 0,
              rects: [[rect[0] - cardWidth / 2, rect[1] - cardHeight / 2, rect[0] + cardWidth / 2, rect[1] + cardHeight / 2]]
            };
